CREATE TABLE IF NOT EXISTS releases (id BIGINT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(255) NOT NULL, source_url TEXT, source_key CHAR(64) UNIQUE, platform VARCHAR(100), language VARCHAR(100), release_date DATE, trailer_url TEXT, summary TEXT, status ENUM('pending','sending','published','rejected') NOT NULL DEFAULT 'pending', published_message_id BIGINT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, published_at DATETIME NULL, INDEX(status));
